import React, { useEffect, useState } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import Swal from "sweetalert2";

export default function ParentFeePage() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [summary, setSummary] = useState(null);
  const [amount, setAmount] = useState("");

  const fetchFee = async () => {
    if (!admissionNo.trim()) return toast.error("Please enter admission number");
    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${admissionNo}`);
      if (res.data.success && res.data.data) {
        setSummary(res.data.data);
        toast.success("Fee record loaded!");
      } else {
        setSummary(null);
        toast.error("No record found!");
      }
    } catch (err) {
      console.error(err);
      toast.error("Failed to load fee structure");
    }
  };

  const payNow = async () => {
    const amt = Number(amount);
    if (!amt || amt <= 0) return toast.error("Enter valid amount");

    const ok = await Swal.fire({
      title: `Pay ₹${amt}?`,
      text: "Proceed to simulated payment?",
      showCancelButton: true,
    });
    if (!ok.isConfirmed) return;

    try {
      const res = await axios.post("http://localhost:5000/api/fees/pay", {
        admissionNo,
        amount: amt,
        method: "simulated",
      });
      if (res.data.success) {
        toast.success("Payment successful!");
        fetchFee(); // refresh data
      } else {
        toast.error(res.data.error || "Payment failed");
      }
    } catch (err) {
      toast.error("Payment failed");
    }
  };

  return (
    <div className="fee-page">
      <Toaster />
      <h2>💳 Pay School Fees</h2>

      <div className="search-box">
        <input
          type="text"
          value={admissionNo}
          onChange={(e) => setAdmissionNo(e.target.value)}
          placeholder="Enter Admission Number (e.g. STU001)"
        />
        <button onClick={fetchFee}>Search</button>
      </div>

      {!summary && <p className="info-text">Enter admission number to view fee details.</p>}

      {summary && (
        <div className="fee-card">
          <h3>Fee Structure ({summary.academicYear})</h3>
          <div dangerouslySetInnerHTML={{ __html: summary.notes }} />

          <table className="fee-table">
            <thead>
              <tr>
                <th>Particulars</th>
                <th>Amount (₹)</th>
              </tr>
            </thead>
            <tbody>
              {summary.items.map((item) => (
                <tr key={item.key}>
                  <td>{item.title}</td>
                  <td>{item.amount}</td>
                </tr>
              ))}
              <tr className="fee-total">
                <td><b>Total</b></td>
                <td><b>₹{summary.items.reduce((sum, i) => sum + i.amount, 0)}</b></td>
              </tr>
            </tbody>
          </table>

          <div className="pay-section">
            <input
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="Enter amount to pay"
            />
            <button onClick={payNow}>Pay Now</button>
            <button onClick={() => setAmount(summary.items.reduce((sum, i) => sum + i.amount, 0))}>
              Pay Full
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
